class AsyncDataTreeNavigator {
    constructor(a) {
        this.a = a;
    }
    current() {
        const current = this.a.current();
        if (current === null) {
            return null;
        }
        return current.element;
    }
    previous() {
        this.a.previous();
        return this.current();
    }
    first() {
        this.a.first();
        return this.current();
    }
    last() {
        this.a.last();
        return this.current();
    }
    next() {
        this.a.next();
        return this.current();
    }
}
